import { BrowserRouter, Routes, Route, useLocation, useNavigate } from "react-router-dom";
import { useState, useEffect } from "react";
import Login from "./Login";
import Sign from "./Sign";
import Contact from "./Contact";
import Cart from "./Cart";
import "./App.css";
import Cat from "./Cat";
import Rabbit from "./Rabbit";
import Guinea from "./Guinea";
import Chinchilla from "./Chinchilla";
import Hamster from "./Hamster";


function Layout() {
    const location = useLocation();
    const navigate = useNavigate();
    const [isAuthenticated, setIsAuthenticated] = useState(!!localStorage.getItem("token"));

    // Handle Logout
    const handleLogout = () => {
        localStorage.removeItem("token"); // Remove token
        setIsAuthenticated(false); // Update state
        navigate("/Login"); // Redirect to login
    };

    // Update auth state when token changes
    useEffect(() => {
        setIsAuthenticated(!!localStorage.getItem("token"));
    }, []);

    const hideSearchAndCategories =
        location.pathname === "/Sign" ||
        location.pathname === "/Contact" ||
        location.pathname === "/Login" ||
        location.pathname === "/Cart";

    return (
        <div>
            <header>
                <a href="/">Home </a>
                {!isAuthenticated && <a href="/Sign">Sign Up </a>}
                <a href="/Contact">Contact </a>
                {isAuthenticated && <a href="/Cart">Cart </a>}
                {isAuthenticated ? (
                    <a href="/Login" onClick={handleLogout}>Logout</a>
                ) : (
                    <a href="/Login">Login</a>
                )}
            </header>

            {!hideSearchAndCategories && (
                <div>
                    <input type="search" placeholder="Search .." />
                    <div className="dropdown">
                        <button className="dropbtn">Categories</button>
                        <div className="dropdown-content">
                            <a href="/Cat">Cats</a>
                            <a href="/Rabbit">Rabbits</a>
                            <a href="/Guinea">Guinea pigs</a>
                            <a href="/Chinchilla">Chinchillas</a>
                            <a href="/Hamster">Hamsters</a>
                        </div>
                    </div>
                </div>
            )}




            <Routes>
                <Route path="/Sign" element={<Sign />} />
                <Route path="/Login" element={<Login setIsAuthenticated={setIsAuthenticated} />} />
                <Route path="/Contact" element={<Contact />} />
                <Route path="/Cart" element={isAuthenticated ? <Cart /> : <Login />} />
                <Route path="/Cat" element={<Cat />} />
                <Route path="/Rabbit" element={<Rabbit />} />
                <Route path="/Guinea" element={<Guinea />} />
                <Route path="/Chinchilla" element={<Chinchilla />} />
                <Route path="/Hamster" element={<Hamster />} />
            </Routes>
        </div>
    );
}

function App() {
    return (
        <BrowserRouter>
            <Layout />
        </BrowserRouter>
    );
}

export default App;
